# ============================================================================
# ABFverify - Gift order tools: image downloads + Copy info button (v1)
# ============================================================================
# WHAT IT DOES
#   On Finance -> Gift Orders:
#   1. Pictures now download as IMAGE FILES, not a ZIP. "Download all"
#      saves every picture of the order one after another (photo_1,
#      photo_2, ...), and each thumbnail also gets a small download icon
#      so you can save a single picture.
#   2. New "Copy info" button on every order card: one click copies all
#      the delivery details, ready to paste like this:
#         Sender's name: ...
#         Receiver's name: ...
#         Address: ...
#         City: ...
#         State: ...
#         Zip code: ...
#         Phone number: ...
#         Size: ...        (only when the order has a size)
#         Note: ...        (only when the order has a note)
#
# Safe to re-run: every step checks first and skips what is already done.
#
# HOW TO RUN
#   1. Copy this file into your project folder (next to manage.py).
#   2. In PowerShell, from that folder:
#        powershell -ExecutionPolicy Bypass -File .\gift-order-tools.ps1
#   3. Then:
#        git add .
#        git commit -m "gift order image downloads + copy info"
#        git push
#   4. After Render shows "Deploy live", open the Render Shell and run:
#        python manage.py collectstatic --noinput
#      (No "migrate" needed - no database changes.)
# ============================================================================

$ErrorActionPreference = "Stop"

function Read-Utf8([string]$p)  { [IO.File]::ReadAllText($p) }
function Write-Utf8([string]$p, [string]$c) {
    [IO.File]::WriteAllText($p, $c, (New-Object System.Text.UTF8Encoding($false)))
}
function Decode([string]$b64) { [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)) }
function Backup-Once([string]$p) {
    $bak = "$p.bak-tools"
    if (-not (Test-Path $bak)) { Copy-Item $p $bak }
}
function Count-Occurrences([string]$hay, [string]$needle) {
    $n = 0; $i = 0
    while (($i = $hay.IndexOf($needle, $i)) -ge 0) { $n++; $i += $needle.Length }
    return $n
}

# ---------- locate the project root ----------
$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root "manage.py"))) {
    Write-Host "ERROR: manage.py not found here." -ForegroundColor Red
    Write-Host "cd into your project folder (the one that contains manage.py) and run again." -ForegroundColor Yellow
    exit 1
}
Write-Host "Project root: $root" -ForegroundColor Cyan
Write-Host "UPDATE VERSION: v1 (gift image downloads + copy info)" -ForegroundColor Magenta

$PHOTO_VIEW_B64 = ""
$URL_A_B64 = "ICAgIHBhdGgoImdpZnQtb3JkZXJzLzxpbnQ6cGs+L3VwZGF0ZS8iLCB2aWV3cy5naWZ0X29yZGVyX3VwZGF0ZSwgbmFtZT0iZmluYW5jZV9naWZ0X29yZGVyX3VwZGF0ZSIpLA=="
$URL_R_B64 = ""
$GO_HTML_B64 = ""
$CSS2_B64 = ""

# ---------- 1) finance/views.py: per-photo download view ----------
Write-Host "`n[1/4] Adding the per-photo download view..." -ForegroundColor Green
$fvPath = Join-Path $root "finance\views.py"
if (-not (Test-Path $fvPath)) {
    Write-Host "  WARNING: finance\views.py not found - skipping." -ForegroundColor Yellow
} else {
    $fv = Read-Utf8 $fvPath
    if ($fv.Contains("def gift_order_photo_download")) {
        Write-Host "  already present, skipping" -ForegroundColor DarkGray
    } else {
        Backup-Once $fvPath
        if (-not $fv.EndsWith("`n")) { $fv += "`r`n" }
        $fv += (Decode $PHOTO_VIEW_B64).Replace("`n", "`r`n")
        Write-Utf8 $fvPath $fv
        Write-Host "  gift_order_photo_download view added" -ForegroundColor DarkGray
    }
}

# ---------- 2) finance/urls.py: per-photo route ----------
Write-Host "`n[2/4] Adding the per-photo download route..." -ForegroundColor Green
$fuPath = Join-Path $root "finance\urls.py"
if (-not (Test-Path $fuPath)) {
    Write-Host "  WARNING: finance\urls.py not found - skipping." -ForegroundColor Yellow
} else {
    $hadCrlf = (Read-Utf8 $fuPath).Contains("`r`n")
    $fu = (Read-Utf8 $fuPath).Replace("`r`n", "`n")
    if ($fu.Contains("finance_gift_order_photo_download")) {
        Write-Host "  route already present, skipping" -ForegroundColor DarkGray
    } else {
        $a = Decode $URL_A_B64
        if ((Count-Occurrences $fu $a) -ne 1) {
            Write-Host "  WARNING: gift-order update route not found in finance\urls.py." -ForegroundColor Yellow
            Write-Host "  Run the gifts installer (v4) first, then this one again." -ForegroundColor Yellow
        } else {
            Backup-Once $fuPath
            $fu = $fu.Replace($a, (Decode $URL_R_B64))
            if ($hadCrlf) { $fu = $fu.Replace("`n", "`r`n") }
            Write-Utf8 $fuPath $fu
            Write-Host "  route added: gift-orders/<id>/photos/<n>/download/" -ForegroundColor DarkGray
        }
    }
}

# ---------- 3) templates/finance/gift_orders.html: new page ----------
Write-Host "`n[3/4] Updating the Gift Orders page..." -ForegroundColor Green
$goPath = Join-Path $root "templates\finance\gift_orders.html"
if (-not (Test-Path $goPath)) {
    Write-Host "  WARNING: templates\finance\gift_orders.html not found - skipping." -ForegroundColor Yellow
} else {
    $go = Read-Utf8 $goPath
    if ($go.Contains("js-copy-info")) {
        Write-Host "  page already updated, skipping" -ForegroundColor DarkGray
    } else {
        Backup-Once $goPath
        Write-Utf8 $goPath (Decode $GO_HTML_B64)
        Write-Host "  Download all + per-photo downloads + Copy info button added" -ForegroundColor DarkGray
    }
}

# ---------- 4) static/css/finance.css: styles ----------
Write-Host "`n[4/4] Adding the styles..." -ForegroundColor Green
$fcPath = Join-Path $root "static\css\finance.css"
if (-not (Test-Path $fcPath)) {
    Write-Host "  WARNING: static\css\finance.css not found - skipping." -ForegroundColor Yellow
} else {
    $fc = Read-Utf8 $fcPath
    if ($fc.Contains("go-photo-view")) {
        Write-Host "  styles already present, skipping" -ForegroundColor DarkGray
    } else {
        Backup-Once $fcPath
        $fc = $fc.TrimEnd() + (Decode $CSS2_B64)
        Write-Utf8 $fcPath $fc
        Write-Host "  styles appended" -ForegroundColor DarkGray
    }
}

# ---------- done ----------
Write-Host "`n============================================" -ForegroundColor Cyan
Write-Host " Done! Next steps:" -ForegroundColor Cyan
Write-Host "============================================" -ForegroundColor Cyan
Write-Host ""
Write-Host "1. Check the changes:" -ForegroundColor White
Write-Host "     findstr /C:""gift_order_photo_download"" finance\views.py" -ForegroundColor Gray
Write-Host "     findstr /C:""finance_gift_order_photo_download"" finance\urls.py" -ForegroundColor Gray
Write-Host "     findstr /C:""js-copy-info"" templates\finance\gift_orders.html" -ForegroundColor Gray
Write-Host "   Each command should print a line." -ForegroundColor Gray
Write-Host ""
Write-Host "2. Publish to Render:" -ForegroundColor White
Write-Host "     git add ." -ForegroundColor Gray
Write-Host "     git commit -m ""gift order image downloads + copy info""" -ForegroundColor Gray
Write-Host "     git push" -ForegroundColor Gray
Write-Host ""
Write-Host "3. Wait until Render shows 'Deploy live', then in the Render Shell run:" -ForegroundColor White
Write-Host "     python manage.py collectstatic --noinput" -ForegroundColor Gray
Write-Host "   (No migrate needed - no database changes in this update.)" -ForegroundColor Gray
Write-Host ""
Write-Host "Then open Finance -> Gift Orders: Download all now saves real image" -ForegroundColor White
Write-Host "files (no more ZIP), and Copy info copies the full delivery details" -ForegroundColor White
Write-Host "of the order, ready to paste anywhere." -ForegroundColor White
